package com.wealthflow;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.beans.factory.annotation.Value;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api") public class ChargebackController {private final KafkaTemplate<String,ChargebackEvent> kafka;private final ChargebackRepository repo;private final WorkflowRepository workflows;private final String topic;public ChargebackController(KafkaTemplate<String,ChargebackEvent> k,ChargebackRepository r,WorkflowRepository w,@Value("${wealthflow.topic:soa.s08.t24.events}")String t){kafka=k;repo=r;workflows=w;topic=t;}
 public record ShareRequest(String id,BigDecimal share){} public record CalculateRequest(BigDecimal totalAmount,List<ShareRequest> allocations){} public record CalculationResponse(String chargebackId,BigDecimal originalTotal,List<AllocationEngine.Line> exactShares,BigDecimal roundingResidual,List<AllocationEngine.Line> finalAllocations,BigDecimal reconciledTotal,boolean reconciled){}
 @PostMapping("/chargebacks/calculate") public ResponseEntity<?> calculate(@RequestBody CalculateRequest r){try{var result=AllocationEngine.allocate(r.totalAmount(),r.allocations().stream().map(x->new AllocationEngine.Share(x.id(),x.share())).toList());var id=UUID.randomUUID().toString();var response=new CalculationResponse(id,r.totalAmount(),result.lines(),result.residual(),result.lines(),result.reconciledTotal(),result.reconciled());return ResponseEntity.ok(response);}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error","VALIDATION_ERROR","message",e.getMessage()));}}
 @PostMapping("/chargebacks/{id}/finalize") public ResponseEntity<?> finalizeChargeback(@PathVariable("id") String id,@RequestBody CalculationResponse r,org.springframework.security.core.Authentication auth){if(!id.equals(r.chargebackId())||!r.reconciled())return ResponseEntity.unprocessableEntity().body(Map.of("error","RECONCILIATION_FAILED"));String eventId=UUID.randomUUID().toString();String ownerId=auth.getName();var event=new ChargebackEvent(eventId,"ChargebackFinalized",id,ownerId,r.originalTotal(),r.reconciledTotal(),"DEMO",Instant.now());repo.save(new ChargebackRecord(id,eventId,ownerId,r.reconciledTotal()));kafka.send(topic,id,event);return ResponseEntity.accepted().body(Map.of("chargebackId",id,"status","FINALIZED","eventId",eventId));}
 @GetMapping("/workflows/{id}") public ResponseEntity<?> workflow(@PathVariable("id") String id,org.springframework.security.core.Authentication auth){var row=workflows.findById(id);if(row.isEmpty())return ResponseEntity.accepted().body(Map.of("chargebackId",id,"status","PENDING_EVENT_CONSUMPTION"));var w=row.get();boolean officer=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_BILLING_OFFICER"));if(!officer&&!w.getOwnerId().equals(auth.getName()))return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("error","FORBIDDEN"));return ResponseEntity.ok(Map.of("chargebackId",id,"eventId",w.getEventId(),"status",w.getStatus(),"totalBilledAmount",w.getTotalBilledAmount(),"finalAllocatedAmount",w.getFinalAllocatedAmount(),"rateVersion",Objects.toString(w.getRateVersion(),""),"finalizedAt",w.getFinalizedAt()));}}
